// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        c.seedMarket{value: 1 ether}(1000);

        address user1 = address(0x123);
        vm.deal(user1, 1 ether);
        vm.prank(user1);
        c.getFreeKilo();

        address user2 = address(0x456);
        vm.deal(user2, 1 ether);
        vm.prank(user2);
        c.getFreeKilo();

        bool ok;
        vm.prank(user2);
        try c.getFreeKilo() { ok = true; } catch { ok = false; }

        assertTrue(ok == false);
    }
}
